    H[4]=(H[4]+e)>>>0; H[5]=(H[5]+f)>>>0; H[6]=(H[6]+g)>>>0; H[7]=(H[7]+h)>>>0;
  }
  const out = Buffer.alloc(32);
  for (let i = 0; i < 8; i++) out.writeUInt32BE(H[i], i * 4);
  return out;
}

function hmacSha256Base64(secretStr, msgBuf) {
  const blockSize = 64;
  let k = Buffer.from(secretStr, 'utf8');
  if (k.length > blockSize) k = sha256(k);
  if (k.length < blockSize) {
    const padded = Buffer.alloc(blockSize);
    k.copy(padded);
    k = padded;
  }
  const ipad = Buffer.alloc(blockSize);
  const opad = Buffer.alloc(blockSize);
  for (let i = 0; i < blockSize; i++) { ipad[i] = k[i] ^ 0x36; opad[i] = k[i] ^ 0x5c; }
  const inner = sha256(Buffer.concat([ipad, msgBuf]));
  return sha256(Buffer.concat([opad, inner])).toString('base64');
}

const input = $input.first().json;
const binary = $input.first().binary || {};
const secret = $env.WC_WEBHOOK_SECRET;
const signature = input.headers?.['x-wc-webhook-signature'];

const deliveryId = input.headers?.['x-wc-webhook-delivery-id'] ||
  input.headers?.['x-wc-webhook-id'] ||
  ('wc-' + Date.now() + '-' + Math.random().toString(36).slice(2));

const orderData = input.body || input;
const wooOrderId = orderData.id;
const wooStatus = orderData.status;

let signature_ok = false;
let expectedSignature = null;

if (!secret) {
  signature_ok = true;
} else if (signature) {
  try {
    if (binary?.data?.data) {
      const rawBuffer = Buffer.from(binary.data.data, 'base64');
      expectedSignature = hmacSha256Base64(secret, rawBuffer);
      signature_ok = (expectedSignature === signature);
    }
    if (!signature_ok) {
      const bodyStr = JSON.stringify(orderData);
      expectedSignature = hmacSha256Base64(secret, Buffer.from(bodyStr, 'utf8'));
      signature_ok = (expectedSignature === signature);
    }
  } catch(e) {
    signature_ok = false;
    expectedSignature = 'ERR: ' + e.message;
  }
}

const lineItem = (orderData.line_items || [])[0] || {};
const savia_whatsapp = (orderData.meta_data || []).find(m => m.key === '_savia_whatsapp')?.value || '';
const savia_talla = (orderData.meta_data || []).find(m => m.key === '_savia_talla')?.value || '';
const savia_metodo_pago = (orderData.meta_data || []).find(m => m.key === '_savia_metodo_pago')?.value || '';
const billing_phone = savia_whatsapp || (orderData.billing?.phone || '').replace(/[^0-9]/g, '');

const telefono = billing_phone || '';
const producto_nombre = lineItem.name || '';
const talla = savia_talla || '';
const mp_transaction_id = orderData.transaction_id || null;
const woo_product_id = lineItem.product_id != null ? lineItem.product_id : null;
const woo_variation_id = lineItem.variation_id != null ? lineItem.variation_id : null;
const monto_cop = orderData.total ? Math.round(parseFloat(orderData.total)) : null;

return [{ json: {
  signature_ok,
  expected_signature: expectedSignature,
  received_signature: signature,
  evento_id: deliveryId,
  woo_order_id: wooOrderId,
  woo_status: wooStatus,
  mp_transaction_id,
  monto_cop,
  payload: orderData,
  telefono,
  billing_name: orderData.billing?.first_name || '',
  producto_nombre,
  woo_product_id,
  woo_variation_id,
  talla,
  savia_metodo_pago,
  s_telefono: telefono || '__NULL__',
  s_woo_product_id: woo_product_id != null ? String(woo_product_id) : '__NULL__',
  s_woo_variation_id: woo_variation_id != null ? String(woo_variation_id) : '__NULL__',
  s_producto_nombre: producto_nombre || '__NULL__',
  s_talla: talla || '__NULL__',
  s_monto_cop: monto_cop != null ? String(monto_cop) : '__NULL__',
  s_woo_order_id: wooOrderId != null ? String(wooOrderId) : '__NULL__',
  s_mp_transaction_id: mp_transaction_id || '__NULL__'
}}];

